import { Button, Slider } from "@mui/material";
import React, { useEffect, useState } from "react";
import data from "../Sentence.json";
import Swal from "sweetalert2";
import { DragDropContext, Droppable, Draggable } from "react-beautiful-dnd";
import ".././styles/style.css";
import { useNavigate } from "react-router-dom";
import { DragDropContainer, DropTarget } from "react-drag-drop-container";
import useWebSocket, { ReadyState } from "react-use-websocket";
import { SendLogData } from "../config/wslog.js";
import logconfig from "../config/dbconfig";
import ReactGA from "react-ga4";
import red from "../Img/red.png";
import green from "../Img/green.png";
import { Dropdown } from "react-bootstrap";

const Kriyavisheshan_level2 = () => {
  const [pageName, setpageName] = useState("Level-2");
  const navigate = useNavigate();
  let [randomNumber, setRandomNumber] = useState(0);
  let [randomNumberArray, setRandomNumberArray] = useState([0]);
  let [showMessage, setShowMessage] = useState(false);
  let [sentArray, setSentArray] = useState([]);
  let [lastItem, setLastItem] = useState("");
  let [isDisableNext, setIsDisableNext] = useState(true);
  let [skipCount, setSkipCount] = useState(0);
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });

  useEffect(() => {
    let sentence = data[1].level2[randomNumber].sentence;
    sentence = sentence.replace(/[.()]/g, "");
    let array = sentence.split(" ");
    //setting the last element of an array to allow drag and drop for that element only.
    setLastItem(array[array.length - 1]);
    setSentArray(array);
  }, [randomNumberArray]);

  const handleVerify = () => {
    let mainSentence = data[1].level2[randomNumber].correctSentence;
    mainSentence = mainSentence.replace(/[]+/g, "").toLowerCase();
    let formedSentence = sentArray.join(" ");
    formedSentence = formedSentence.replace(/[]+/g, "").toLowerCase();
    // console.log("Main sententence", mainSentence);
    // console.log("formed sentence", formedSentence);

    if (mainSentence == formedSentence) {
      // toast.success("Correct!", {
      //   position: "top-center",
      //   autoClose: 2000,
      // });
      setIsDisableNext(false);
      setShowMessage(true);
    } else {
      setShowMessage(true);
      setIsDisableNext(true);
    }

    ReactGA.event({
      action: `Eng10|Adverb|Clicked on "verify" button of level-3`,
      category: `Eng10|verify button clicked`,
      label: `Eng10|Clicked on verify button`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "Verify",
      "Clicked",
      "checked selected option is right or wrong",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  const restart = () => {
    navigate("/");
  };

  const handleNext = () => {
    setIsDisableNext(true);
    setShowMessage(false);
    randomNumber = Math.floor(Math.random() * data[1].level2.length);
    if (randomNumberArray.length - 1 !== 10) {
      if (randomNumberArray.includes(randomNumber)) {
        handleNext();
      } else {
       
        setRandomNumberArray((prevState) => [...prevState, randomNumber]);
        setRandomNumber(randomNumber);
        console.log(randomNumberArray, "randomNumberArray");
      }
    } else {
      Swal.fire({
        text: `आपने सफलतापूर्वक 10 में से ${
          10 - skipCount
        } वाक्य पुरे किये है!`,
        showClass: {
          popup: "animate__animated animate__fadeInDown",
        },
        hideClass: {
          popup: "animate__animated animate__fadeOutUp",
        },
        customClass: {
          title: "completeion-text",
          htmlContainer: "completeion-text",
        },
        confirmButtonText: "पुनः आरंभ करें",
      }).then((result) => {
        if (result.isConfirmed) {
          navigate("/letusverify");
        }
      });
    }
    ReactGA.event({
      action: `Eng10|Adverb|Clicked on "NEXT" button of level-3`,
      category: `Eng10|next button clicked`,
      label: `Eng10|Clicked on next button`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "NEXT",
      "Clicked",
      "Clicked to move to the next sentence",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  const onDragComplete = (result) => {
    setShowMessage(false);
    if (!result.destination) return;
    const arr = [...sentArray];
    if (arr[result.source.index] === lastItem) {
      //console.log(`${lastItem} is dragging`);
      // Only allow dragging of the last element
      arr.splice(result.source.index, 1); // Remove the last element from its source position
      arr.splice(result.destination.index, 0, lastItem); // Insert it at the desired position

      // Updating the list
      setSentArray(arr);
    }

    ReactGA.event({
      action: `Eng10|Adverb|${lastItem} dropped at index ${result.source.index}`,
      category: `Eng10|Dropping of word inside the droppable area`,
      label: `Eng10|Dropping of adverb`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "Dropping of adverb",
      "drop",
      "Dropping an adverb at proper place to form a meaningful sentence",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  const handleChange = (event) => {
    switch (event.target.value) {
      case "level1":
        navigate("/launchpage/englishactivity/level1");
        ReactGA.event({
          action: `Eng10|Adverb|Clicked on dropdown to navigate to the level-1`,
          category: `Eng10|level Dropdown clicked`,
          label: `Eng10|Clicked on Level Dropdown`,
        });

        SendLogData(
          sendJsonMessage,
          pageName,
          "Dropdown",
          "Clicked",
          "Clicked to navigate to level-1",
          [{ input: "", answer: "", result: "" }],
          [
            {
              popuptype: "",
              popuptext: "",
            },
          ],
          [{ hint: "" }]
        );
        break;
      case "level2":
        navigate("/launchpage/englishactivity/level1/level2");
        ReactGA.event({
          action: `Eng10|Adverb|Clicked on dropdown to navigate to the level-2`,
          category: `Eng10|level Dropdown clicked`,
          label: `Eng10|Clicked on Level Dropdown`,
        });

        SendLogData(
          sendJsonMessage,
          pageName,
          "Dropdown",
          "Clicked",
          "Clicked to navigate to level-2",
          [{ input: "", answer: "", result: "" }],
          [
            {
              popuptype: "",
              popuptext: "",
            },
          ],
          [{ hint: "" }]
        );
        break;
      case "level3":
        navigate("/launchpage/englishactivity/level1/level2/level3");
        ReactGA.event({
          action: `Eng10|Adverb|Clicked on dropdown to navigate to the level-3`,
          category: `Eng10|level Dropdown clicked`,
          label: `Eng10|Clicked on Level Dropdown`,
        });

        SendLogData(
          sendJsonMessage,
          pageName,
          "Dropdown",
          "Clicked",
          "Clicked to navigate to level-3",
          [{ input: "", answer: "", result: "" }],
          [
            {
              popuptype: "",
              popuptext: "",
            },
          ],
          [{ hint: "" }]
        );
        break;
    }
  };

  const handleSkip = () => {
    let newSkipCount = skipCount + 1;
    setSkipCount(newSkipCount);
    handleNext();
    ReactGA.event({
      action: `Eng10|Adverb|Clicked on "SKIP" button of level-3`,
      category: `Eng10|SKIP button clicked`,
      label: `Eng10|Clicked on SKIP button`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "SKIP",
      "Clicked",
      "Clicked to skip the sentence",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  return (
    <div className="" style={{ height: "100%" }}>
      <div
        className=""
        style={{
          height: "100%",
          fontSize: "1rem",
          background: "#FCF5F5",
          borderRadius: "14px",
          overflow: "hidden auto",
          overflowX: "hidden",
        }}
      >
        <div className="row-md-auto d-flex flex-column ">
          <div className="col ">
            <div className="row-md-auto d-flex">
              <div className="">
                <h6
                  className=""
                  style={{
                    marginTop: "15%",
                    marginLeft: "1vh",
                    color: "#220730",
                  }}
                >
                  <strong style={{}}>स्तर 2</strong>
                </h6>
              </div>
              <div className="col text-center">
                <h5 style={{ paddingTop: "10px", color: "#4E0870" }}>
                  <strong>क्रिया विशेषण की स्थिति। </strong>
                </h5>
              </div>
              <div className="col-md-auto">
                <Dropdown className="d-flex justify-content-end">
                  <Dropdown.Toggle
                    variant="success"
                    id="dropdown-basic"
                    style={{ background: "#A372D1" }}
                  >
                    स्तर चुने
                  </Dropdown.Toggle>

                  <Dropdown.Menu style={{ background: "#F7F1FC" }}>
                    <Dropdown.Item
                      href="#/ll5_level1"
                      style={{ color: "#350B5B" }}
                    >
                      स्तर 1
                    </Dropdown.Item>
                    <Dropdown.Item
                      href="#/ll5_level2"
                      style={{ color: "" }}
                      disabled="true"
                    >
                      स्तर 2
                    </Dropdown.Item>
                    <Dropdown.Item
                      href="#/ll5_level3"
                      style={{ color: "#350B5B" }}
                    >
                      स्तर 3
                    </Dropdown.Item>
                  </Dropdown.Menu>
                </Dropdown>
              </div>
            </div>
            <div className="col-md-auto">
              {/* <div className="text-start d-flex">
                <p style={{ color: "#220730", marginTop: "" }}>
                  <img
                    className="img-fluid"
                    src={green}
                    style={{ width: "4vh" }}
                  ></img>{" "}
                  सही जवाब
                  <img
                    className="img-fluid"
                    src={red}
                    style={{ width: "4vh", marginLeft: "1vh" }}
                  ></img>{" "}
                  गलत जवाब
                </p>
              </div> */}
            </div>
          </div>

          <div className="">
            <div className="row mb-3 mt-3">
              <div className="d-flex align-items-center">
                <span className="me-3">वाक्य</span>

                <Slider
                  defaultValue={0}
                  step={1}
                  min={0}
                  max={10}
                  value={randomNumberArray.length - 1}
                  color="success"
                  marks
                  valueLabelDisplay="on"
                  sx={{
                    "& .MuiSlider-mark": {
                      width: 12,
                      height: 12,
                      borderRadius: "50%",
                    },
                  }}
                />

                <span
                  className="ms-3"
                  style={{
                    height: "40px",
                    width: "45px",
                    borderRadius: "50%",
                    backgroundColor: "#FFC000",
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                  }}
                >
                  {randomNumberArray.length - 1}/{10}
                </span>
              </div>
            </div>
            <div className="row mb-3">
              <div className="text-center">
                <b>वाक्य</b>: {data[1].level2[randomNumber].sentence}
                {/* data.level2[randomNumber].sentence */}
              </div>
            </div>
            <div
              className="row text-center mb-4 mt-3"
              style={{
                background: "#fdf5e6",
                borderRadius: "25px",
                opacity: "1",
                color: "black",
                padding: "1.2%",
                margin: "0%",
              }}
            >
              <div className="row-md-auto ">
                <DragDropContext onDragEnd={onDragComplete}>
                  <Droppable droppableId="characters" direction="horizontal">
                    {(provided) => (
                      <div
                        className="col d-flex justify-content-center align-items-center"
                        {...provided.droppableProps}
                        ref={provided.innerRef}
                      >
                        {sentArray.map((item, index) => (
                          <Draggable
                            key={index}
                            draggableId={"" + index}
                            index={index}
                          >
                            {(provided) => (
                              <div
                                className={
                                  item == lastItem
                                    ? "item-card-adverb"
                                    : "item-card"
                                }
                                // className="item-card"
                                ref={provided.innerRef}
                                {...provided.draggableProps}
                                {...provided.dragHandleProps}
                              >
                                <p>{item} </p>
                              </div>
                            )}
                          </Draggable>
                        ))}
                        {provided.placeholder}
                      </div>
                    )}
                  </Droppable>
                </DragDropContext>
              </div>
            </div>
            <div className="row mb-1">
              <div className="d-flex justify-content-around">
                {skipCount == 11 ? (
                  <Button
                    variant="contained"
                    style={{
                      borderRadius: "5px",
                      borderColor: "#4E0870",
                      color: "#4E0870",
                      backgroundColor: "#DEC3F7",
                    }}
                    onClick={handleSkip}
                    disabled
                  >
                    <b>छोड़ दे</b>
                  </Button>
                ) : (
                  <Button
                    style={{
                      borderRadius: "5px",
                      borderColor: "#4E0870",
                      color: "#4E0870",
                      backgroundColor: "#DEC3F7",
                    }}
                    variant="contained"
                    onClick={handleSkip}
                  >
                    <b>छोड़ दे</b>
                  </Button>
                )}
                {/* <Button variant="contained" onClick={handleSkip}>
                  छोड़ दे
                </Button> */}

                <Button
                  color="success"
                  variant="contained"
                  onClick={handleVerify}
                  style={{
                    borderRadius: "5px",
                    borderColor: "#4E0870",
                    color: "#4E0870",
                    backgroundColor: "#DEC3F7",
                  }}
                >
                  <b>जाँच करें</b>
                </Button>
                <Button
                  disabled={isDisableNext}
                  style={{
                    borderRadius: "5px",
                    borderColor: "#4E0870",
                    color: "#4E0870",
                    backgroundColor: "#DEC3F7",
                  }}
                  onClick={handleNext}
                >
                  <b>
                    {randomNumberArray.length - 1 == 10
                      ? "समाप्त"
                      : "अगला वाक्य"}
                  </b>
                </Button>
              </div>
            </div>
            <div className="row justify-content-center mt-3">
              {showMessage && (
                <div
                  style={{
                    height: "auto",
                    width: "auto",
                    background: "#ffffff",
                    boxShadow: "0px 0px 10px rgba(0, 0, 0, 0.5)",
                    padding: "1.56%",
                    borderRadius: "50px",
                  }}
                >
                  <div>
                    {isDisableNext ? (
                      <>
                        गलत उत्तर!{" "}
                        <span className="text-danger"><b>{lastItem}</b></span> गलत
                        स्थान पर जमाया गया है
                        <br />
                        <b>संकेत</b>:{" "}
                        {data[1].level2[randomNumber].feedbackMessage}
                      </>
                    ) : (
                      <span>
                        सही उत्तर!{" "}
                        <span className="text-success"><b>{lastItem}</b></span> सही
                        स्थान पर जमाया गया है।
                      </span>
                    )}
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Kriyavisheshan_level2;
