import React from "react";
import { Route, Routes, useParams } from "react-router-dom";
import ActStartPopupContent from "./components/ActStartPopupContent";
import { useTranslation } from "react-i18next";
import { useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { changeLang } from "./store/Store";
import Language from "./Language";
import "../src/App.css";
import { Ll5_launchpage } from "./components/Ll5_launchpage";
import Ll5_levelstart from "./components/Ll5_levelstart";
import LL5_theory from "./components/LL5_theory";
import Ll5_levelchoice from "./components/Ll5_levelchoice";
import Ll5_procedure from "./components/Ll5_procedure";
import LL5_Level1 from "./components/LL5_Level1";
import LL5_Level2 from "./components/LL5_Level2";
import LL5_Level3 from "./components/LL5_Level3";
import { L_QuizComponent } from "./quiz/L_QuizComponent";
import L_HelpComponent from "./Help/L_HelpComponent";

const App = () => {
  const { t, i18n } = useTranslation();
  const { id } = useParams();
  let dispatch = useDispatch();
  let { firstStore } = useSelector((globalState) => globalState);
  useEffect(() => {
    //console.log("parameter id " + firstStore?.lang);

    if (id == "en") {
      alert("in app en : ", id);
      i18n.changeLanguage("en");
      dispatch(changeLang("en"));
    }
    if (id == "hn") {
      alert("in app hn : ", id);
      i18n.changeLanguage("hn");
      dispatch(changeLang("hn"));
    }
  }, []);
  return (
    <Routes>
      <Route path="/" element={<Ll5_launchpage />} />
      <Route path="/lang=:id" element={<App />} />
      <Route path="/levels_start" element={<Ll5_levelchoice />} />
      <Route path="/letusverify" element={<Ll5_levelstart />} />
      <Route path="/ll5_Level1" element={<LL5_Level1 />} />
      <Route path="/ll5_Level2" element={<LL5_Level2 />} />
      <Route path="/ll5_Level3" element={<LL5_Level3 />} />
      <Route path="/theory_page" element={<LL5_theory />} />
      <Route path="/procedure_page" element={<Ll5_procedure />} />
      <Route path="/help_page" element={<L_HelpComponent />} />

      <Route
        path="/letusverify/relations-functions/actstartpopupcontent"
        element={<ActStartPopupContent />}
      />
           <Route path="/quiz" element={<L_QuizComponent />} />
    </Routes>
  );
};

export default App;
